def contains(sorted_items, target):
    def helper(lo, hi):
        if lo > hi:
            return False
        mid = (lo + hi) // 2
        if sorted_items[mid] == target:
            return True
        if sorted_items[mid] < target:
            return helper(mid + 1, hi)
        return helper(lo, mid - 1)
    return helper(0, len(sorted_items) - 1)

